/bin/bash -lc "python3 - <<'PY'
import urllib.request
base='https://raw.githubusercontent.com/NVIDIA/cuda-samples/db3eea23946bca2e90a75eca2b5b3e07158a9e11/'
for path in ['Samples/5_Domain_Specific/MonteCarloMultiGPU/MonteCarloMultiGPU.cpp','Samples/5_Domain_Specific/MonteCarloMultiGPU/MonteCarlo_kernel.cu','Samples/5_Domain_Specific/MonteCarloMultiGPU/CMakeLists.txt']:
 print('\\nSOURCE',base+path)
 try:
  print(urllib.request.urlopen(base+path,timeout=30).read().decode())
 except Exception as e: print(type(e).__name__,str(e))
PY"

